from .models import Entry


class EntryForm(forms.ModelForm):
    class Meta:
        model = Entry
        fields = ["title", "author", "status", "rating", "notes"]
        widgets = {"notes": forms.Textarea(attrs={"rows": 4})}

    def clean_rating(self):
        rating = self.cleaned_data.get("rating")
        if rating is not None and not 1 &lt;= rating &lt;= 5:
            raise forms.ValidationError("Rating must be between 1 and 5.")
        return rating

    def clean(self):
        cleaned = super().clean()
        if cleaned.get("rating") and cleaned.get("status") != Entry.Status.DONE:
            self.add_error("rating", "Only finished books can be rated.")
        return cleaned
</code></pre> <p><code>self.add_error("rating", ...)</code> attaches a cross-field error to a specific field instead of the form-wide <code>__all__</code> list, so it appears next to the rating input where the user will look for it.</p>

books/views.py<pre><code>from django.db.models import Count
from django.shortcuts import get_object_or_404, redirect, render
from django.views.decorators.http import require_POST

from .forms import EntryForm
from .models import Entry


def entry_list(request):
    entries = Entry.objects.all()
    status = request.GET.get("status")
    if status in Entry.Status.values:
        entries = entries.filter(status=status)
    else:
        status = None
    counts = dict(Entry.objects.values_list("status").annotate(n=Count("id")))
    tabs = [(value, label, counts.get(value, 0)) for value, label in Entry.Status.choices]
    return render(request, "books/entry_list.html",
                  {"entries": entries, "status": status, "tabs": tabs})


def entry_detail(request, pk):
    entry = get_object_or_404(Entry, pk=pk)
    return render(request, "books/entry_detail.html", {"entry": entry})


def entry_form(request, pk=None):
    entry = get_object_or_404(Entry, pk=pk) if pk else None
    form = EntryForm(request.POST or None, instance=entry)
    if request.method == "POST" and form.is_valid():
        entry = form.save()
        return redirect(entry)
    return render(request, "books/entry_form.html", {"form": form, "entry": entry})


@require_POST
def entry_finish(request, pk):
    entry = get_object_or_404(Entry, pk=pk)
    entry.mark_finished()
    return redirect(entry)


def entry_delete(request, pk):
    entry = get_object_or_404(Entry, pk=pk)
    if request.method == "POST":
        entry.delete()
        return redirect("books:list")
    return render(request, "books/entry_confirm_delete.html", {"entry": entry})
</code></pre> <p>The counts query is worth reading closely. <code>values_list("status").annotate(n=Count("id"))</code> groups by status and counts each group in one query, producing pairs like <code>("want", 1)</code>; <code>dict()</code> turns them into a lookup. Statuses with no books are missing from that result, so <code>counts.get(value, 0)</code> fills them in. Validating <code>status</code> against <code>Entry.Status.values</code> means a hand-edited URL can't produce a confusing empty page.</p> <p><code>EntryForm(request.POST or None, instance=entry)</code> is a compact idiom: on GET, <code>request.POST</code> is an empty (falsy) QueryDict, so the form is unbound. One view handles both create (<code>pk=None</code>) and edit.</p>

