                .annotate(going=Count("rsvps", filter=Q(rsvps__answer=RSVP.Answer.YES)))
                .prefetch_related(Prefetch("rsvps", queryset=RSVP.objects.filter(user=request.user),
                                           to_attr="my_rsvp")))
